export type Post = {
  id: number;
  title: string;
  body: string;
};

const posts: Post[] = [];
let nextId = 1;

export function addPost({ title, body }: { title: string; body: string }) {
  posts.push({ id: nextId++, title, body });
}

export function getPosts(): Post[] {
  return [...posts];
}

